package main

import (
	"context"
	"crypto/subtle"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB
var apiKeys sync.Map
var expectedAPIKey []byte

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost dbname=app sslmode=require")
	if err != nil {
		log.Fatal(err)
	}

	// Load the expected API key from the environment instead of hardcoding it.
	keyHex := os.Getenv("API_KEY")
	if keyHex == "" {
		log.Fatal("API_KEY environment variable is required")
	}
	expectedAPIKey, err = hex.DecodeString(keyHex)
	if err != nil || len(expectedAPIKey) != 32 {
		log.Fatal("API_KEY must be a 32-byte hex-encoded value")
	}
}

// PageConfig holds pagination settings derived from request
type PageConfig struct {
	Offset   int64
	PageSize int64
	OrderCol string
	OrderDir string
}

// AuthMiddleware validates API key using constant-time comparison
func AuthMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		key := r.Header.Get("X-API-Key")
		if key == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		keyBytes, err := hex.DecodeString(key)
		if err != nil || len(keyBytes) != 32 {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		if subtle.ConstantTimeCompare(keyBytes, expectedAPIKey) != 1 {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next(w, r)
	}
}

var allowedOrderCols = map[string]string{
	"id":         "id",
	"created_at": "created_at",
	"updated_at": "updated_at",
	"name":       "name",
	"priority":   "priority",
}

// parsePageConfig extracts pagination from query params
func parsePageConfig(r *http.Request) (*PageConfig, error) {
	pc := &PageConfig{
		Offset:   0,
		PageSize: 20,
		OrderCol: "id",
		OrderDir: "ASC",
	}

	if v := r.URL.Query().Get("page_size"); v != "" {
		size, err := strconv.ParseInt(v, 10, 16)
		if err != nil {
			return nil, fmt.Errorf("invalid page_size")
		}
		if size <= 0 || size > 100 {
			size = 20
		}
		pc.PageSize = size
	}

	if v := r.URL.Query().Get("offset"); v != "" {
		off, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid offset")
		}
		if off < 0 {
			off = 0
		}
		pc.Offset = off
	}

	if v := r.URL.Query().Get("order_by"); v != "" {
		if col, ok := allowedOrderCols[v]; ok {
			pc.OrderCol = col
		}
	}

	if v := r.URL.Query().Get("order_dir"); v != "" {
		upper := strings.ToUpper(v)
		if upper == "ASC" || upper == "DESC" {
			pc.OrderDir = upper
		}
	}

	return pc, nil
}

// buildPaginationClause constructs the ORDER BY / LIMIT / OFFSET clause
// Uses identifier-safe values from allowlist for ORDER BY
// LIMIT and OFFSET are numeric and formatted directly (safe for integers)
func buildPaginationClause(pc *PageConfig) string {
	return fmt.Sprintf("ORDER BY %s %s LIMIT %d OFFSET %d",
		pc.OrderCol, pc.OrderDir, pc.PageSize, pc.Offset)
}

// TaskFilter represents validated filter criteria
type TaskFilter struct {
	Status   string
	Assignee string
	MinScore int
	HasScore bool
}

func parseFilter(r *http.Request) *TaskFilter {
	f := &TaskFilter{}
	if v := r.URL.Query().Get("status"); v != "" {
		// Only allow known statuses
		switch v {
		case "open", "closed", "pending", "in_progress":
			f.Status = v
		}
	}
	f.Assignee = r.URL.Query().Get("assignee")
	if v := r.URL.Query().Get("min_score"); v != "" {
		score, err := strconv.Atoi(v)
		if err == nil {
			f.MinScore = score
			f.HasScore = true
		}
	}
	return f
}

// buildFilterQuery constructs parameterized WHERE clause
func buildFilterQuery(f *TaskFilter) (string, []interface{}) {
	clauses := []string{}
	args := []interface{}{}
	paramIdx := 1

	if f.Status != "" {
		clauses = append(clauses, fmt.Sprintf("status = $%d", paramIdx))
		args = append(args, f.Status)
		paramIdx++
	}

	if f.Assignee != "" {
		clauses = append(clauses, fmt.Sprintf("assignee = $%d", paramIdx))
		args = append(args, f.Assignee)
		paramIdx++
	}

	if f.HasScore {
		clauses = append(clauses, fmt.Sprintf("score >= $%d", paramIdx))
		args = append(args, f.MinScore)
		paramIdx++
	}

	if len(clauses) == 0 {
		return "WHERE 1=1", args
	}
	return "WHERE " + strings.Join(clauses, " AND "), args
}

// ListTasks handles GET /api/tasks with filtering and pagination
func ListTasks(w http.ResponseWriter, r *http.Request) {
	pc, err := parsePageConfig(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	filter := parseFilter(r)
	whereClause, args := buildFilterQuery(filter)
	paginationClause := buildPaginationClause(pc)

	query := fmt.Sprintf("SELECT id, name, status, assignee, score, created_at FROM tasks %s %s",
		whereClause, paginationClause)

	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()

	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		http.Error(w, "query failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, status, assignee string
		var score int
		var createdAt time.Time
		if err := rows.Scan(&id, &name, &status, &assignee, &score, &createdAt); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		line := fmt.Sprintf(`  {"id":%d,"name":%q,"status":%q,"assignee":%q,"score":%d,"created_at":%q}`,
			id, name, status, assignee, score, createdAt.Format(time.RFC3339))
		w.Write([]byte(line))
	}
	w.Write([]byte("\n]"))
}

func main() {
	http.HandleFunc("/api/tasks", AuthMiddleware(ListTasks))
	log.Fatal(http.ListenAndServe(":8080", nil))
}
